function mintFungible(
    IERC20 foreignAsset,
    uint256 nativeDeposit,
    uint256 foreignDeposit,
    address from,
    address to
) external override nonReentrant returns (uint256 liquidity) {
    IERC20Extended lp = wrapper.tokens(foreignAsset);
    require( lp != IERC20Extended(_ZERO_ADDRESS), "VaderPoolV2::mintFungible: Unsupported Token" );
    (uint112 reserveNative, uint112 reserveForeign, ) = getReserves( foreignAsset );
    nativeAsset.safeTransferFrom(from, address(this), nativeDeposit);
    foreignAsset.safeTransferFrom(from, address(this), foreignDeposit);
    PairInfo storage pair = pairInfo[foreignAsset];
    uint256 totalLiquidityUnits = pair.totalSupply;
    if (totalLiquidityUnits == 0) liquidity = nativeDeposit;
    else liquidity = VaderMath.calculateLiquidityUnits( nativeDeposit, reserveNative, foreignDeposit, reserveForeign, totalLiquidityUnits );
    require( liquidity > 0, "VaderPoolV2::mintFungible: Insufficient Liquidity Provided" );
    pair.totalSupply = totalLiquidityUnits + liquidity;
    _update( foreignAsset, reserveNative + nativeDeposit, reserveForeign + foreignDeposit, reserveNative, reserveForeign );
    lp.mint(to, liquidity);
    emit Mint(from, to, nativeDeposit, foreignDeposit);
}

function mintSynth(
    IERC20 foreignAsset,
    uint256 nativeDeposit,
    address from,
    address to
) external override nonReentrant supportedToken(foreignAsset) returns (uint256 amountSynth) {
    nativeAsset.safeTransferFrom(from, address(this), nativeDeposit);
    ISynth synth = synthFactory.synths(foreignAsset);
    if (synth == ISynth(_ZERO_ADDRESS)) synth = synthFactory.createSynth( IERC20Extended(address(foreignAsset)) );
    (uint112 reserveNative, uint112 reserveForeign, ) = getReserves( foreignAsset );
    amountSynth = VaderMath.calculateSwap( nativeDeposit, reserveNative, reserveForeign );
    _update( foreignAsset, reserveNative + nativeDeposit, reserveForeign, reserveNative, reserveForeign );
    synth.mint(to, amountSynth);
}

function calculateLoss(
    uint256 originalVader,
    uint256 originalAsset,
    uint256 releasedVader,
    uint256 releasedAsset
) public pure returns (uint256 loss) {
    uint256 originalValue = ((originalAsset * releasedVader) / releasedAsset) + originalVader;
    uint256 releasedValue = ((releasedAsset * releasedVader) / releasedAsset) + releasedVader;
    if (originalValue > releasedValue) loss = originalValue - releasedValue;
}
